{
  "technical_and_design_decisions": [
    "Use GitHub Actions for CI infrastructure (U3, U8) since repositories are hosted on GitHub.",
    "Implement shell-based REST client for StreamController (U1) as a Bash script using curl for simplicity and portability.",
    "Adapt Redis counter from Spring XD to Spring Cloud Stream (U2) as a functional-style source/sink/processor module using Spring Cloud Stream 4.x APIs.",
    "Resolve module-dependent JARs for Boot loader (U4) by extending Spring Boot's PropertiesLauncher or implementing a custom classloader that adds external dependencies (e.g., database drivers) to the module classpath at runtime.",
    "Bootify ModuleLauncher (U5) by converting it to a Spring Boot 3.x application with @SpringBootApplication, leveraging Spring Boot's property management, configuration, and lifecycle.",
    "Investigation for PHD/HDFS port (U6) will be a time-boxed spike focusing on classloading strategies (e.g., shaded JARs, isolated classloaders) to make HDFS dependencies available in root classpath at runtime.",
    "Add REST support for stream commands (U7) by implementing REST controllers in spring-cloud-data that delegate to StreamController, following RESTful conventions and securing endpoints with Spring Security if needed.",
    "All projects target Java 17+, Spring Boot 3.x, Spring Cloud 2022.x/2023.x, and use Maven as build tool."
  ],
  "assumptions": [
    "Developer has full access to spring-cloud-data, spring-cloud-stream-modules, and Spring XD legacy codebases locally.",
    "Existing StreamController REST API is stable and documented; shell script will cover core operations (deploy, undeploy, status, list).",
    "Redis counter adaptation (U2) requires only the counter logic, not the entire XD module framework; will be built as a standalone Spring Cloud Stream module.",
    "CI pipelines (U3, U8) require standard Maven build, unit/integration test execution, and artifact publishing to Maven Central or GitHub Packages; no complex deployment stages.",
    "Module-dependent JAR resolution (U4) assumes modules declare external dependencies in a standardized descriptor (e.g., META-INF/spring-modules.properties).",
    "ModuleLauncher (U5) currently exists as a standalone Java class; bootification includes adding Spring Boot starters, configuration properties, and command-line argument parsing.",
    "PHD/HDFS investigation (U6) is a research spike; no production code implementation is included in this increment.",
    "REST support for stream commands (U7) will be added to the existing spring-cloud-data web module; authentication/authorization is out of scope.",
    "All estimates assume a single experienced Spring ecosystem developer; no ramp-up time included."
  ],
  "activities": [
    {
      "activity_id": "A1.1",
      "activity_name": "Design shell/CLI interface for StreamController REST API",
      "activity_description": "Define commands, parameters, and output formats for shell script to invoke StreamController REST endpoints (deploy, undeploy, status, list streams).",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A1.2",
      "activity_name": "Implement shell script for StreamController REST API",
      "activity_description": "Write Bash script using curl to call REST endpoints, handle authentication, parse JSON responses, and provide user-friendly output.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A1.3",
      "activity_name": "Test shell script against StreamController",
      "activity_description": "Execute script against running StreamController instance, validate all commands, handle error cases, and fix issues.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A1.4",
      "activity_name": "Document shell script usage",
      "activity_description": "Add usage documentation to project README or separate guide, including examples and environment setup.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A2.1",
      "activity_name": "Analyze Spring XD Redis counter module",
      "activity_description": "Review XD Redis counter source code, understand its interfaces, configuration, and dependencies.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A2.2",
      "activity_name": "Design Spring Cloud Stream Redis counter module",
      "activity_description": "Define module type (source/sink/processor), configuration properties, and integration with Spring Cloud Stream functional programming model.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A2.3",
      "activity_name": "Implement Redis counter module for Spring Cloud Stream",
      "activity_description": "Code the module using Spring Cloud Stream 4.x APIs, including RedisTemplate usage, serialization, and configuration binding. Write unit tests.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2.4",
      "activity_name": "Test Redis counter module in streaming pipeline",
      "activity_description": "Create a sample pipeline (e.g., source -> counter -> sink), deploy via StreamController, verify counting functionality and dashboard feed.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2.5",
      "activity_name": "Document Redis counter module",
      "activity_description": "Add module documentation: configuration options, deployment instructions, and example pipeline definitions.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3.1",
      "activity_name": "Set up GitHub Actions workflow for spring-cloud-data",
      "activity_description": "Create YAML workflow files for build, test (unit/integration), and artifact publishing on push/PR. Configure JDK 17, Maven caching.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A3.2",
      "activity_name": "Configure CI secrets, caching, and publishing",
      "activity_description": "Set up GitHub secrets for GPG signing, Maven Central credentials, and configure dependency caching for faster builds.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3.3",
      "activity_name": "Test CI pipeline for spring-cloud-data",
      "activity_description": "Trigger workflows via test commits, verify build success, test execution, and artifact deployment to staging repository.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3.4",
      "activity_name": "Document CI setup for spring-cloud-data",
      "activity_description": "Add CI documentation to project wiki/README: workflow overview, required secrets, and how to release.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A4.1",
      "activity_name": "Analyze current module loading and Boot loader mechanism",
      "activity_description": "Study spring-cloud-data module deployment code, Boot loader implementation, and how modules are currently classloaded.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A4.2",
      "activity_name": "Design solution for module-dependent JAR resolution",
      "activity_description": "Design approach to declare, resolve, and inject external JARs (e.g., database drivers) into module classpath at launch time. Consider using PropertiesLauncher or custom URLClassLoader.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A4.3",
      "activity_name": "Implement module-dependent JAR resolution and Boot loader modification",
      "activity_description": "Modify module launcher to read dependency descriptors, download/resolve JARs (via Maven/Aether), and add to module classpath. Update Boot loader if needed.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A4.4",
      "activity_name": "Test with module requiring external driver",
      "activity_description": "Create test module (e.g., JDBC source) requiring PostgreSQL driver, deploy via modified loader, verify driver loads and connection works.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A4.5",
      "activity_name": "Document module-dependent JAR approach",
      "activity_description": "Document descriptor format, resolution process, and how module developers declare external dependencies.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A5.1",
      "activity_name": "Analyze current ModuleLauncher",
      "activity_description": "Review ModuleLauncher code, its responsibilities, configuration handling, and extension points.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A5.2",
      "activity_name": "Refactor ModuleLauncher to Spring Boot application",
      "activity_description": "Convert to @SpringBootApplication, add spring-boot-starter, migrate configuration to application.properties/YAML, use Spring Boot's CommandLineRunner or ApplicationRunner.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A5.3",
      "activity_name": "Add property management and CP augmentation support",
      "activity_description": "Implement support for Spring Boot's @ConfigurationProperties, environment-specific configs, and design extension points for future CP (ClassPath) augmentation.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A5.4",
      "activity_name": "Test ModuleLauncher with various configurations",
      "activity_description": "Run ModuleLauncher with different profiles, property overrides, and module deployment scenarios to ensure compatibility.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A5.5",
      "activity_name": "Document ModuleLauncher bootification changes",
      "activity_description": "Update developer guide: new configuration options, migration steps, and extension mechanisms.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A6.1",
      "activity_name": "Research PHD and HDFS module from Spring XD",
      "activity_description": "Study Pivotal HD (PHD) distribution specifics and XD HDFS module implementation, dependencies, and runtime requirements.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A6.2",
      "activity_name": "Investigate classloading and dependency management approaches for HDFS",
      "activity_description": "Evaluate strategies: shaded JARs, isolated classloaders, Spring Boot's launcher, or OSGi. Assess impact on root classpath and module isolation.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A6.3",
      "activity_name": "Prototype HDFS dependency handling approach",
