      "most_likely_effort": 8
    },
    {
      "activity_id": "A6.4",
      "activity_name": "Document findings and recommendation for HDFS port",
      "activity_description": "Produce a design document with recommended approach, trade-offs, and implementation roadmap for future work.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A7.1",
      "activity_name": "Design REST API for stream commands",
      "activity_description": "Define REST endpoints (POST /streams/deploy, DELETE /streams/{name}, GET /streams, etc.), request/response payloads, and error handling.",
      "most_likely_effort": 4
    },
