      "activity_id": "A7.2",
      "activity_name": "Implement REST controllers for stream commands",
      "activity_description": "Create Spring MVC controllers in spring-cloud-data, inject StreamController, implement endpoint logic, validation, and exception handling.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A7.3",
      "activity_name": "Integrate REST endpoints with StreamController",
      "activity_description": "Ensure StreamController exposes necessary operations, handle asynchronous deployment status, and propagate events.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A7.4",
      "activity_name": "Test REST endpoints with shell script",
      "activity_description": "Use shell script from U1 to exercise all new REST endpoints, verify integration, and fix issues.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A7.5",
      "activity_name": "Document REST API for stream commands",
      "activity_description": "Generate OpenAPI/Swagger documentation, add to project docs, and provide usage examples.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A8.1",
      "activity_name": "Set up GitHub Actions workflow for spring-cloud-stream-modules",
      "activity_description": "Create YAML workflow files for build, test, and artifact publishing. Configure JDK 17, Maven caching, and module-specific build steps.",
